&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Auto Futures: &lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;a href=&quot;https://www.autofutures.tv/news-features/autonomous-trucking-group-gatik-secures-investment-from-nippon-express-holdings/s/e125e5df-220b-42b6-b2df-754f54d602a9&quot;&gt;Autonomous Trucking Group Gatik Secures Investment From NIPPON EXPRESS HOLDINGS&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
