 76%-100%&amp;quot;,&amp;quot;di-ts&amp;quot;:{&amp;quot;ts_bd&amp;quot;:false,&amp;quot;ts_fs&amp;quot;:11,&amp;quot;ts_ff&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;ts_it&amp;quot;:false,&amp;quot;ts_sc&amp;quot;:false,&amp;quot;ts_st&amp;quot;:false,&amp;quot;ts_tw&amp;quot;:400,&amp;quot;ts_un&amp;quot;:false,&amp;quot;ts_va&amp;quot;:&amp;quot;nor&amp;quot;,&amp;quot;ts_bgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#d4edbc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}}]}},&amp;quot;ddefe-t&amp;quot;:&amp;quot;Travel&amp;quot;,&amp;quot;type&amp;quot;:&amp;quot;dropdown&amp;quot;}&quot;&gt;Minimal: 1%-10%&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
